import Foundation

// Rule-generated skill drills. A port of web/src/lib/drills; DrillTests replays content/drill-test-vectors.json
// (generated by the web code) so both apps produce identical problems from the same seed.

/// Small seeded PRNG (mulberry32), identical to the web version.
struct SeededRng {
    private var a: UInt32

    init(seed: UInt32) { a = seed }

    mutating func next() -> Double {
        a = a &+ 0x6d2b79f5
        var t = a
        t = (t ^ (t >> 15)) &* (t | 1)
        t ^= t &+ ((t ^ (t >> 7)) &* (t | 61))
        return Double(t ^ (t >> 14)) / 4294967296.0
    }

    /// Integer in [min, max], inclusive.
    mutating func int(_ min: Int, _ max: Int) -> Int {
        min + Int(floor(next() * Double(max - min + 1)))
    }

    mutating func pick<T>(_ items: [T]) -> T {
        items[Int(floor(next() * Double(items.count)))]
    }
}

enum TrackId: String, Codable, CaseIterable, Hashable {
    case mentalMath = "mental-math"
    case estimation = "estimation"
}

struct DrillSpec: Hashable {
    let track: TrackId
    let level: Int
    let seed: UInt32
}

struct DrillProblem: Hashable {
    let prompt: String
    let answer: Double
    /// A short trick shown after answering.
    let hint: String?
}

struct TrackInfo {
    let name: String
    let blurb: String
    let levels: [String]
    let problems: Int
    /// Total time for a round, in seconds, when the track is timed.
    let timeLimitSeconds: Double?
    var maxLevel: Int { levels.count }
}

enum Drills {
    static let tracks: [TrackId: TrackInfo] = [
        .mentalMath: TrackInfo(
            name: "Mental math",
            blurb: "Quick sums and shortcuts",
            levels: [
                "Add two 2-digit numbers",
                "Subtract 2-digit numbers",
                "Add 3-digit and 2-digit numbers",
                "Multiply by a single digit",
                "Shortcut multipliers: 5, 9, 11, 25",
                "Easy percentages: 10%, 25%, 50%",
                "Percentages: 5%, 15%, 20%, 30%",
                "Squares ending in 5 and near-mirror products",
            ],
            problems: 3,
            timeLimitSeconds: 45
        ),
        .estimation: TrackInfo(
            name: "Estimation",
            blurb: "Fermi-style guesses",
            levels: ["Time conversions", "Rates over time", "Volumes and fitting things in", "Fermi chains"],
            problems: 2,
            timeLimitSeconds: nil
        ),
    ]

    static func info(_ track: TrackId) -> TrackInfo { tracks[track]! }

    /// The problems for one drill round. Deterministic for a given spec.
    static func generateRound(_ spec: DrillSpec) -> [DrillProblem] {
        var rng = SeededRng(seed: spec.seed)
        var seen = Set<String>()
        var out: [DrillProblem] = []
        var guardCount = 0
        let wanted = info(spec.track).problems
        while out.count < wanted && guardCount < 50 {
            guardCount += 1
            let p = spec.track == .mentalMath ? mentalMath(spec.level, &rng) : estimation(spec.level, &rng)
            if seen.contains(p.prompt) { continue }
            seen.insert(p.prompt)
            out.append(p)
        }
        return out
    }

    // MARK: Mental math

    private static func mentalMath(_ level: Int, _ r: inout SeededRng) -> DrillProblem {
        switch min(max(level, 1), 8) {
        case 1:
            let a = r.int(11, 89), b = r.int(11, 98)
            return DrillProblem(prompt: "\(a) + \(b)", answer: Double(a + b), hint: "Add the tens, then the ones.")
        case 2:
            let a = r.int(32, 99), b = r.int(11, a - 5)
            return DrillProblem(prompt: "\(a) − \(b)", answer: Double(a - b), hint: "Subtract the tens first, then the ones.")
        case 3:
            let a = r.int(101, 989), b = r.int(12, 98)
            return DrillProblem(prompt: "\(a) + \(b)", answer: Double(a + b), hint: "Round one number to the next ten, add, then fix the difference.")
        case 4:
            let a = r.int(12, 99), b = r.int(3, 9)
            return DrillProblem(prompt: "\(a) × \(b)", answer: Double(a * b), hint: "Split it: \(a / 10 * 10) × \(b) plus \(a % 10) × \(b).")
        case 5:
            let m = r.pick([5, 9, 11, 25])
            let a = m == 25 ? r.int(2, 24) * 4 : r.int(12, 99)
            let hints = [
                5: "× 5 is half of × 10.",
                9: "× 9 is × 10 minus the number itself.",
                11: "× 11 is × 10 plus the number itself.",
                25: "× 25 is a quarter of × 100.",
            ]
            return DrillProblem(prompt: "\(a) × \(m)", answer: Double(a * m), hint: hints[m])
        case 6:
            let p = r.pick([10, 25, 50])
            let base = p == 25 ? r.int(2, 40) * 4 * 10 : r.int(2, 40) * 10
            let hints = [
                10: "10% is one tenth: move the decimal point.",
                25: "25% is a quarter: halve, then halve again.",
                50: "50% is half.",
            ]
            return DrillProblem(prompt: "\(p)% of \(base)", answer: Double(base * p) / 100, hint: hints[p])
        case 7:
            let p = r.pick([5, 15, 20, 30])
            let base = r.int(1, 12) * 20
            let hints = [
                5: "5% is half of 10%.",
                15: "15% is 10% plus half of 10%.",
                20: "20% is double 10%.",
                30: "30% is three times 10%.",
            ]
            return DrillProblem(prompt: "\(p)% of \(base)", answer: Double(base * p) / 100, hint: hints[p])
        default:
            if r.next() < 0.5 {
                let t = r.int(1, 9)
                let a = t * 10 + 5
                return DrillProblem(
                    prompt: "\(a)²",
                    answer: Double(a * a),
                    hint: "For a number ending in 5: tens × (tens + 1), then write 25. Here \(t) × \(t + 1) = \(t * (t + 1)), so \(a * a)."
                )
            }
            let mid = r.int(3, 9) * 10
            let d = r.int(1, 4)
            return DrillProblem(
                prompt: "\(mid - d) × \(mid + d)",
                answer: Double(mid * mid - d * d),
                hint: "It is \(mid)² − \(d)², because (m − d)(m + d) = m² − d²."
            )
        }
    }

    // MARK: Estimation

    private static let unitSeconds: [String: Int] = ["second": 1, "minute": 60, "hour": 3600, "day": 86400, "week": 604800]

    private static func estimation(_ level: Int, _ r: inout SeededRng) -> DrillProblem {
        switch min(max(level, 1), 4) {
        case 1:
            let pairs: [(String, String, Int, Int)] = [
                ("second", "hour", 2, 12), ("second", "day", 2, 9), ("minute", "day", 2, 9), ("minute", "week", 2, 6), ("hour", "week", 2, 9),
            ]
            let (small, big, lo, hi) = r.pick(pairs)
            let n = r.int(lo, hi)
            let answer = Double(n * unitSeconds[big]!) / Double(unitSeconds[small]!)
            let per = unitSeconds[big]! / unitSeconds[small]!
            return DrillProblem(prompt: "How many \(small)s are in \(n) \(big)\(n > 1 ? "s" : "")?", answer: answer, hint: "\(per) \(small)s in a \(big), times \(n).")
        case 2:
            let t = r.int(0, 2)
            if t == 0 {
                let bpm = r.pick([60, 70, 80]), days = r.int(2, 9)
                return DrillProblem(prompt: "A heart beats \(bpm) times a minute. How many beats in \(days) days?", answer: Double(bpm * 60 * 24 * days), hint: "\(bpm) × 60 minutes × 24 hours × \(days).")
            }
            if t == 1 {
                let per = r.pick([2, 3, 5]), weeks = r.int(2, 8)
                return DrillProblem(prompt: "A tap drips \(per) drops every second. How many drops in \(weeks) weeks?", answer: Double(per * 604800 * weeks), hint: "\(per) × 604,800 seconds per week × \(weeks).")
            }
            let kmh = r.pick([4, 5, 6]), hours = r.int(5, 40)
            return DrillProblem(prompt: "Someone walks \(kmh) km every hour without stopping. How many metres in \(hours) hours?", answer: Double(kmh * 1000 * hours), hint: "\(kmh) km = \(kmh * 1000) m, times \(hours).")
        case 3:
            let t = r.int(0, 2)
            if t == 0 {
                let s = r.int(2, 9)
                return DrillProblem(prompt: "A cube is \(s) m on each side. How many 1-litre bottles of water fit in it? (1 m³ = 1,000 litres)", answer: Double(s * s * s * 1000), hint: "\(s)³ = \(s * s * s) cubic metres, times 1,000.")
            }
            if t == 1 {
                let a = r.int(2, 6), b = r.int(2, 8), c = r.int(2, 5)
                return DrillProblem(prompt: "A room is \(a) m × \(b) m with a \(c) m ceiling. How many 1-litre bottles of air would fill it? (1 m³ = 1,000 litres)", answer: Double(a * b * c * 1000), hint: "\(a) × \(b) × \(c) = \(a * b * c) cubic metres, times 1,000.")
            }
            let s = r.int(2, 6)
            let side = s * 100
            return DrillProblem(prompt: "How many 1 cm cubes fit inside a cube that is \(s) m on each side? (1 m = 100 cm)", answer: Double(side * side * side), hint: "\(side) cm on each side, cubed.")
        default:
            let t = r.int(0, 2)
            if t == 0 {
                let millions = r.int(2, 9), litres = r.pick([2, 3])
                return DrillProblem(prompt: "A city has \(millions) million people and each drinks \(litres) litres of water a day. How many litres does it drink in a year (365 days)?", answer: Double(millions) * 1e6 * Double(litres) * 365, hint: "\(millions)M × \(litres) × 365.")
            }
            if t == 1 {
                let students = r.pick([400, 800, 1200, 2000]), msgs = r.pick([20, 30, 50])
                return DrillProblem(prompt: "A school has \(students) students. Each sends \(msgs) messages a day, and the school year has 180 days. How many messages in a school year?", answer: Double(students * msgs * 180), hint: "\(students) × \(msgs) × 180.")
            }
            let cars = r.int(2, 8), km = r.pick([30, 40, 50])
            return DrillProblem(prompt: "A town has \(cars) thousand cars. Each drives \(km) km a day. How many km in a 30-day month?", answer: Double(cars * 1000 * km * 30), hint: "\(cars),000 × \(km) × 30.")
        }
    }

    // MARK: Answers

    /// Parses "1,200", "1.5k", "3m", "2e6", "1.2 million". Returns nil if it is not a number.
    static func parseNumber(_ input: String) -> Double? {
        let s = input.lowercased().filter { !$0.isWhitespace && $0 != "," }
        guard let regex = try? NSRegularExpression(pattern: #"^(-?\d*\.?\d+(?:e[+-]?\d+)?)(k|m|b|thousand|million|billion)?$"#) else { return nil }
        let range = NSRange(s.startIndex..., in: s)
        guard let match = regex.firstMatch(in: s, range: range), let numRange = Range(match.range(at: 1), in: s), let base = Double(s[numRange]) else { return nil }
        var multiplier = 1.0
        if match.range(at: 2).location != NSNotFound, let unitRange = Range(match.range(at: 2), in: s) {
            switch s[unitRange] {
            case "k", "thousand": multiplier = 1e3
            case "m", "million": multiplier = 1e6
            case "b", "billion": multiplier = 1e9
            default: break
            }
        }
        let value = base * multiplier
        return value.isFinite ? value : nil
    }

    struct Judgement {
        let correct: Bool
        let guess: Double?
        let note: String
    }

    static func judge(_ track: TrackId, _ problem: DrillProblem, input: String) -> Judgement {
        guard let guess = parseNumber(input) else { return Judgement(correct: false, guess: nil, note: "That wasn't a number.") }
        if track == .mentalMath {
            let ok = abs(guess - problem.answer) < 1e-9
            return Judgement(correct: ok, guess: guess, note: ok ? "Correct" : "Not quite")
        }
        return Judgement(correct: Scoring.isCloseEnough(guess, problem.answer), guess: guess, note: Scoring.estimationVerdict(guess, problem.answer))
    }
}

// MARK: Levels (80% over the last 20 attempts)

struct SkillProgress: Codable, Hashable {
    var track: TrackId
    var level: Int = 1
    /// Results at the current level, newest last, at most `Skills.window` long.
    var recentResults: [Bool] = []
    var attemptsTotal: Int = 0
    var lastAt: Date = .distantPast
}

enum Skills {
    static let window = 20
    static let threshold = 0.8

    static func shouldLevelUp(_ recent: [Bool]) -> Bool {
        guard recent.count >= window else { return false }
        return Double(recent.suffix(window).filter { $0 }.count) / Double(window) >= threshold
    }

    static func apply(_ progress: SkillProgress, results: [Bool], now: Date) -> (progress: SkillProgress, leveledUp: Bool) {
        var p = progress
        var recent = Array((p.recentResults + results).suffix(window))
        var leveledUp = false
        if p.level < Drills.info(p.track).maxLevel && shouldLevelUp(recent) {
            p.level += 1
            recent = [] // fresh start on the new level
            leveledUp = true
        }
        p.recentResults = recent
        p.attemptsTotal += results.count
        p.lastAt = now
        return (p, leveledUp)
    }

    /// The track practised least recently (never-practised tracks first).
    static func nextTrack(_ all: [SkillProgress]) -> TrackId {
        TrackId.allCases.min { a, b in
            (all.first { $0.track == a }?.lastAt ?? .distantPast) < (all.first { $0.track == b }?.lastAt ?? .distantPast)
        }!
    }
}
